# Verify the rule more carefully
def check_block_colors(grid, row_block, col_block):
    """Check all colors in a block"""
    start_r, start_c = row_block * 3, col_block * 3
    colors = set()
    for r in range(3):
        for c in range(3):
            cell = grid[start_r + r][start_c + c]
            colors.add(cell)
    return sorted(colors)

